package org.pipelineframework.orchestrator.release;

import java.util.HexFormat;
import java.security.MessageDigest;
import com.fasterxml.jackson.databind.SerializationFeature;
import org.junit.jupiter.api.Test;
import org.pipelineframework.config.pipeline.PipelineJson;
import static org.junit.jupiter.api.Assertions.*;

/** Frozen bytes were generated by the old artifact closure, not by this reader's serializer. */
class LegacyPipelineReleaseEvidenceCompatibilityTest {
    private static final String FINGERPRINT = "f5c89332e6eb43c1f973c777eaad899ef16b164315f85f5e6849384ba58aff8d";
    private static final String RESOURCE = "/compatibility/release-evidence/legacy-release-evidence.json";

    @Test void oldEvidenceRetainsExactFingerprintAndSerializedBytesWithNewReader() throws Exception {
        byte[] frozen = frozen();
        var provenance = PipelineJson.mapper().readTree(getClass().getResourceAsStream("/compatibility/release-evidence/provenance.json"));
        assertEquals(provenance.path("fixtureSha256").asText(), HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(frozen)));
        assertFalse(PipelineJson.mapper().readTree(frozen).path("contract").has("rootBoundary"));
        var evidence = PipelineJson.mapper().readValue(frozen, PipelineReleaseEvidence.class);
        assertTrue(evidence.contract().rootBoundary().isEmpty());
        assertEquals(FINGERPRINT, evidence.metadataFingerprint());
        assertArrayEquals(frozen, PipelineJson.mapper().writer().with(SerializationFeature.ORDER_MAP_ENTRIES_BY_KEYS).writeValueAsBytes(evidence));
    }

    @Test void oldFingerprintDoesNotBlessAlteredArtifactOrAddedCanonicalRootBoundary() throws Exception {
        for (String change : java.util.List.of("artifact", "rootBoundary")) {
            var tampered = PipelineJson.mapper().readTree(frozen()).deepCopy();
            if (change.equals("artifact")) {
                ((com.fasterxml.jackson.databind.node.ObjectNode) tampered).put("primaryArtifactDigest", "sha256:" + "b".repeat(64));
            } else {
                ((com.fasterxml.jackson.databind.node.ObjectNode) tampered.path("contract")).put("schemaVersion", 3).putObject("rootBoundary")
                    .put("schemaVersion", 1).put("inputCanonicalTypeId", "Request").put("outputCanonicalTypeId", "Receipt");
            }
            assertEquals(FINGERPRINT, tampered.path("metadataFingerprint").asText());
            var failure = assertThrows(com.fasterxml.jackson.databind.JsonMappingException.class,
                () -> PipelineJson.mapper().treeToValue(tampered, PipelineReleaseEvidence.class));
            assertTrue(failure.getMessage().contains("fingerprint mismatch"), failure.getMessage());
        }
    }

    private byte[] frozen() throws Exception {
        try (var stream = getClass().getResourceAsStream(RESOURCE)) {
            assertNotNull(stream, RESOURCE); return stream.readAllBytes();
        }
    }
}
